      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "The total number of people for the first three days is 260.",
      "evidence": "Sum of daily counts: 50 + 70 + 140 = 260.",
      "weight": 0.10,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "There are 4 remaining days in the week after the first three days.",
      "evidence": "A week consists of 7 days; 7 − 3 = 4.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 6,
      "claim": "The total number of people for the remaining days is 240.",
      "evidence": "Average of 60 people per remaining day: 4 × 60 = 240.",
      "weight": 0.15,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "The total number of people Conor saw that week is 500.",
      "evidence": "Add the totals for the first three days and the remaining days: 260 + 240 = 500.",
      "weight": 0.08,
      "depends_on": [4, 6]
    }
  ],
